import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '6P-CM-1': lesson(['El desarrollo sostenible busca un equilibrio entre la economía (trabajo, riqueza), la sociedad (bienestar de todas las personas) y el medio ambiente (cuidar la naturaleza), sin comprometer el futuro.|El desenvolupament sostenible busca un equilibri entre l’economia (treball, riquesa), la societat (benestar de totes les persones) i el medi ambient (cuidar la natura), sense comprometre el futur.|Sustainable development seeks a balance between the economy (jobs, wealth), society (everyone’s wellbeing) and the environment (caring for nature), without harming the future.', 'Los Objetivos de Desarrollo Sostenible (ODS) son 17 metas mundiales, como acabar con el hambre, agua limpia o acción por el clima.|Els Objectius de Desenvolupament Sostenible (ODS) són 17 metes mundials, com acabar amb la fam, aigua neta o acció pel clima.|The Sustainable Development Goals (SDGs) are 17 world goals, such as ending hunger, clean water and climate action.'],
    'Una fábrica da trabajo pero contamina el río. ¿Es sostenible?|Una fàbrica dona treball però contamina el riu. És sostenible?|A factory provides jobs but pollutes the river. Is it sustainable?', ['Cumple la parte económica, pero no la ambiental.|Complix la part econòmica, però no l’ambiental.|It meets the economic part but not the environmental one.', 'No: tendría que depurar sus vertidos.|No: hauria de depurar els seus abocaments.|No: it would need to treat its waste water.'], [
    Nq('¿Cuántos Objetivos de Desarrollo Sostenible hay?|Quants Objectius de Desenvolupament Sostenible hi ha?|How many Sustainable Development Goals are there?', 17, [10, 5, 30], 'Los aprobó la ONU en 2015.|Els va aprovar l’ONU en 2015.|The UN agreed them in 2015.'),
    M('¿Qué tres partes equilibra el desarrollo sostenible?|Quines tres parts equilibra el desenvolupament sostenible?|Which three parts does sustainable development balance?', 'economía, sociedad y medio ambiente|economia, societat i medi ambient|economy, society and environment', ['deporte, música y arte|esport, música i art|sport, music and art', 'solo la economía|només l’economia|only the economy'], 'Las tres a la vez.|Les tres alhora.|All three at once.'),
    M('¿Qué acción es sostenible?|Quina acció és sostenible?|Which action is sustainable?', 'usar energía solar|usar energia solar|using solar power', ['talar un bosque sin replantar|talar un bosc sense replantar|felling a forest without replanting', 'tirar residuos al mar|tirar residus a la mar|dumping waste at sea'], 'No agota recursos.|No esgota recursos.|It does not use up resources.'),
    TF('El desarrollo sostenible piensa también en las personas del futuro.|El desenvolupament sostenible pensa també en les persones del futur.|Sustainable development also thinks about future generations.', true, 'Satisfacer hoy sin quitar mañana.|Satisfer hui sense llevar demà.|Meeting today’s needs without taking from tomorrow.'),
    M('¿Qué ODS trata de que todo el mundo tenga agua potable?|Quin ODS tracta que tothom tinga aigua potable?|Which SDG aims for everyone to have drinking water?', 'agua limpia y saneamiento|aigua neta i sanejament|clean water and sanitation', ['industria e innovación|indústria i innovació|industry and innovation', 'vida submarina|vida submarina|life below water'], 'El ODS 6.|L’ODS 6.|SDG 6.'),
    M('¿Qué es un recurso renovable?|Què és un recurs renovable?|What is a renewable resource?', 'uno que se regenera, como la madera bien gestionada|un que es regenera, com la fusta ben gestionada|one that regenerates, like well-managed timber', ['el petróleo|el petroli|oil', 'el carbón|el carbó|coal'], 'Se repone si no se abusa.|Es reposa si no se n’abusa.|It renews if not overused.'),
  ]),
  '6P-CM-2': lesson(['El aparato reproductor permite tener hijos. En la pubertad (entre los 9 y los 15 años, aproximadamente) el cuerpo cambia: se crece más deprisa, sale vello, cambia la voz y empiezan la menstruación o la producción de espermatozoides.|L’aparell reproductor permet tindre fills. En la pubertat (entre els 9 i els 15 anys, aproximadament) el cos canvia: es creix més de pressa, ix pèl, canvia la veu i comencen la menstruació o la producció d’espermatozoides.|The reproductive system allows people to have children. In puberty (roughly between 9 and 15) the body changes: you grow faster, body hair appears, the voice changes and periods or sperm production begin.', 'Cada persona tiene su ritmo y todos los cambios son normales. Se pueden hablar con la familia, el profesorado o el personal sanitario.|Cada persona té el seu ritme i tots els canvis són normals. Es poden parlar amb la família, el professorat o el personal sanitari.|Everyone has their own pace and all these changes are normal. You can talk about them with family, teachers or health staff.'],
    '¿Es normal que unos compañeros cambien antes que otros en la pubertad?|És normal que uns companys canvien abans que altres en la pubertat?|Is it normal for some classmates to change earlier than others in puberty?', ['Cada cuerpo tiene su propio ritmo.|Cada cos té el seu propi ritme.|Every body has its own pace.', 'Sí, es totalmente normal.|Sí, és totalment normal.|Yes, it is completely normal.'], [
    M('¿Qué es la pubertad?|Què és la pubertat?|What is puberty?', 'la etapa en que el cuerpo cambia hacia el de un adulto|l’etapa en què el cos canvia cap al d’un adult|when the body changes towards an adult’s', ['una enfermedad|una malaltia|an illness', 'la vejez|la vellesa|old age'], 'Empieza al final de la infancia.|Comença al final de la infància.|It begins at the end of childhood.'),
    M('¿Qué órgano produce los óvulos?|Quin òrgan produïx els òvuls?|Which organ produces egg cells?', 'los ovarios|els ovaris|the ovaries', ['los testículos|els testicles|the testes', 'el estómago|l’estómac|the stomach'], 'Forma parte del aparato reproductor femenino.|Forma part de l’aparell reproductor femení.|They are part of the female reproductive system.'),
    M('¿Qué órgano produce los espermatozoides?|Quin òrgan produïx els espermatozoides?|Which organ produces sperm?', 'los testículos|els testicles|the testes', ['los ovarios|els ovaris|the ovaries', 'los pulmones|els pulmons|the lungs'], 'Forma parte del aparato reproductor masculino.|Forma part de l’aparell reproductor masculí.|They are part of the male reproductive system.'),
    TF('Durante la pubertad es importante la higiene diaria.|Durant la pubertat és important la higiene diària.|Daily hygiene is important during puberty.', true, 'El cuerpo suda más.|El cos sua més.|The body sweats more.'),
    M('Si tienes dudas sobre los cambios de tu cuerpo, ¿qué puedes hacer?|Si tens dubtes sobre els canvis del teu cos, què pots fer?|If you have questions about your body’s changes, what can you do?', 'preguntar a un adulto de confianza o a un sanitario|preguntar a un adult de confiança o a un sanitari|ask a trusted adult or health worker', ['callártelo|callar-t’ho|keep it to yourself', 'creer cualquier vídeo de internet|creure qualsevol vídeo d’internet|believe any internet video'], 'Busca información fiable.|Busca informació fiable.|Look for reliable information.'),
    M('¿Qué cambio es habitual en la pubertad?|Quin canvi és habitual en la pubertat?|Which change is common in puberty?', 'crecer más deprisa|créixer més de pressa|growing faster', ['dejar de crecer para siempre|deixar de créixer per sempre|stopping growing forever', 'perder los dientes de leche a los 15|perdre les dents de llet als 15|losing milk teeth at 15'], 'Se llama «estirón».|Es diu «estirada».|It is called a growth spurt.'),
  ]),
  '6P-CM-3': lesson(['La energía no se crea ni se destruye: se transforma. En una bombilla, la energía eléctrica se transforma en luz y calor; en un coche, la química del combustible en movimiento.|L’energia no es crea ni es destruïx: es transforma. En una bombeta, l’energia elèctrica es transforma en llum i calor; en un cotxe, la química del combustible en moviment.|Energy is neither created nor destroyed: it changes form. In a bulb, electrical energy becomes light and heat; in a car, the fuel’s chemical energy becomes movement.'],
    '¿Qué transformación ocurre en una placa solar?|Quina transformació passa en una placa solar?|What change happens in a solar panel?', ['Recibe luz del sol.|Rep llum del sol.|It receives sunlight.', 'Energía luminosa → energía eléctrica.|Energia lluminosa → energia elèctrica.|Light energy → electrical energy.'], [
    M('En una batidora, la energía eléctrica se transforma sobre todo en…|En una batedora, l’energia elèctrica es transforma sobretot en…|In a blender, electrical energy turns mainly into…', 'movimiento|moviment|movement', ['luz|llum|light', 'química|química|chemical energy'], 'Las cuchillas giran.|Les fulles giren.|The blades spin.'),
    M('Al comer, nuestro cuerpo usa la energía…|En menjar, el nostre cos usa l’energia…|When we eat, our body uses… energy', 'química de los alimentos|química dels aliments|chemical energy from food', ['eléctrica del enchufe|elèctrica de l’endoll|electrical energy from the socket', 'nuclear|nuclear|nuclear'], 'Los alimentos almacenan energía.|Els aliments emmagatzemen energia.|Food stores energy.'),
    TF('La energía desaparece cuando se usa.|L’energia desapareix quan s’usa.|Energy disappears when it is used.', false, 'Se transforma en otras formas, a menudo calor.|Es transforma en altres formes, sovint calor.|It changes into other forms, often heat.'),
    M('En un altavoz, la energía eléctrica se transforma en…|En un altaveu, l’energia elèctrica es transforma en…|In a loudspeaker, electrical energy becomes…', 'sonido|so|sound', ['luz|llum|light', 'química|química|chemical energy'], 'Lo oímos.|El sentim.|We hear it.'),
    M('Una pelota en lo alto de una cuesta tiene energía…|Una pilota dalt d’una costera té energia…|A ball at the top of a slope has… energy', 'potencial|potencial|potential', ['sonora|sonora|sound', 'luminosa|lluminosa|light'], 'Al caer, se convierte en movimiento.|En caure, es convertix en moviment.|As it rolls down, it becomes movement.'),
    M('¿Qué aparato transforma movimiento en electricidad?|Quin aparell transforma moviment en electricitat?|Which device turns movement into electricity?', 'un generador (dinamo)|un generador (dinamo)|a generator (dynamo)', ['una bombilla|una bombeta|a bulb', 'una plancha|una planxa|an iron'], 'Como la dinamo de una bici.|Com la dinamo d’una bici.|Like a bicycle dynamo.'),
  ]),
  '6P-CM-4': lesson(['Las energías renovables vienen de fuentes que no se agotan: sol (solar), viento (eólica), agua (hidráulica), calor de la Tierra (geotérmica) y biomasa.|Les energies renovables vénen de fonts que no s’esgoten: sol (solar), vent (eòlica), aigua (hidràulica), calor de la Terra (geotèrmica) i biomassa.|Renewable energy comes from sources that do not run out: sun (solar), wind, water (hydro), the Earth’s heat (geothermal) and biomass.', 'Las no renovables se acaban y contaminan más: petróleo, carbón, gas natural y uranio (nuclear).|Les no renovables s’acaben i contaminen més: petroli, carbó, gas natural i urani (nuclear).|Non-renewables run out and pollute more: oil, coal, natural gas and uranium (nuclear).'],
    '¿La energía eólica es renovable?|L’energia eòlica és renovable?|Is wind energy renewable?', ['Viene del viento, que no se acaba.|Ve del vent, que no s’acaba.|It comes from wind, which never runs out.', 'Sí, es renovable.|Sí, és renovable.|Yes, it is renewable.'], [
    M('¿Qué fuente de energía no es renovable?|Quina font d’energia no és renovable?|Which energy source is non-renewable?', 'el carbón|el carbó|coal', ['el sol|el sol|the sun', 'el viento|el vent|wind'], 'Tardó millones de años en formarse.|Va tardar milions d’anys a formar-se.|It took millions of years to form.'),
    M('¿Qué energía aprovecha la fuerza del agua de un embalse?|Quina energia aprofita la força de l’aigua d’un embassament?|Which energy uses the force of water in a reservoir?', 'hidráulica|hidràulica|hydroelectric', ['eólica|eòlica|wind', 'solar|solar|solar'], 'Hidro = agua.|Hidro = aigua.|Hydro = water.'),
    TF('Quemar petróleo emite gases que calientan el planeta.|Cremar petroli emet gasos que escalfen el planeta.|Burning oil releases gases that warm the planet.', true, 'Por eso se buscan energías limpias.|Per això es busquen energies netes.|That is why clean energy is needed.'),
    M('¿Qué ventaja tienen las renovables?|Quin avantatge tenen les renovables?|What is an advantage of renewables?', 'no se agotan y contaminan menos|no s’esgoten i contaminen menys|they do not run out and pollute less', ['funcionan sin sol ni viento|funcionen sense sol ni vent|they work with no sun or wind', 'son infinitas en cualquier momento|són infinites en qualsevol moment|they are unlimited at every moment'], 'Pero dependen del tiempo atmosférico.|Però depenen del temps atmosfèric.|But they depend on the weather.'),
    M('La biomasa usa…|La biomassa usa…|Biomass uses…', 'restos vegetales y orgánicos|restes vegetals i orgàniques|plant and organic waste', ['uranio|urani|uranium', 'carbón|carbó|coal'], 'Se considera renovable si se repone.|Es considera renovable si es reposa.|It counts as renewable if replenished.'),
    M('¿Qué energía aprovecha el calor del interior de la Tierra?|Quina energia aprofita la calor de l’interior de la Terra?|Which energy uses heat from inside the Earth?', 'geotérmica|geotèrmica|geothermal', ['eólica|eòlica|wind', 'mareomotriz|maremotriu|tidal'], 'Geo = Tierra; térmica = calor.|Geo = Terra; tèrmica = calor.|Geo = Earth; thermal = heat.'),
  ]),
  '6P-CM-5': lesson(['Los instrumentos de medida nos dan datos precisos: el dinamómetro mide fuerzas, el termómetro temperaturas, el cronómetro tiempos, la balanza masas y el anemómetro la velocidad del viento.|Els instruments de mesura ens donen dades precises: el dinamòmetre mesura forces, el termòmetre temperatures, el cronòmetre temps, la balança masses i l’anemòmetre la velocitat del vent.|Measuring instruments give precise data: a force meter measures forces, a thermometer temperatures, a stopwatch time, scales mass and an anemometer wind speed.', 'Las máquinas compuestas combinan máquinas simples y operadores (engranajes, poleas, bielas) para transmitir el movimiento.|Les màquines compostes combinen màquines simples i operadors (engranatges, politges, bieles) per a transmetre el moviment.|Compound machines combine simple machines and parts (gears, pulleys, connecting rods) to transmit motion.'],
    '¿Con qué medirías la fuerza con que tiras de un muelle?|Amb què mesuraries la força amb què estires una molla?|What would you use to measure how hard you pull a spring?', ['La fuerza se mide en newtons.|La força es mesura en newtons.|Force is measured in newtons.', 'Con un dinamómetro.|Amb un dinamòmetre.|With a force meter (newton meter).'], [
    M('¿Qué mide el anemómetro?|Què mesura l’anemòmetre?|What does an anemometer measure?', 'la velocidad del viento|la velocitat del vent|wind speed', ['la lluvia|la pluja|rainfall', 'la temperatura|la temperatura|temperature'], 'Tiene cazoletas que giran con el viento.|Té cassoletes que giren amb el vent.|It has cups that spin in the wind.'),
    M('¿Qué operador transmite el giro entre dos ruedas dentadas?|Quin operador transmet el gir entre dues rodes dentades?|Which part passes turning motion between two toothed wheels?', 'los engranajes|els engranatges|gears', ['el interruptor|l’interruptor|the switch', 'la pila|la pila|the battery'], 'Sus dientes encajan.|Les seues dents encaixen.|Their teeth mesh together.'),
    M('Una bicicleta es una máquina…|Una bicicleta és una màquina…|A bicycle is a… machine', 'compuesta|composta|compound', ['simple|simple|simple', 'eléctrica obligatoriamente|elèctrica obligatòriament|necessarily electric'], 'Combina ruedas, palancas, cadena y engranajes.|Combina rodes, palanques, cadena i engranatges.|It combines wheels, levers, a chain and gears.'),
    TF('El cronómetro sirve para medir tiempos con precisión.|El cronòmetre servix per a mesurar temps amb precisió.|A stopwatch measures time precisely.', true, 'Mide hasta centésimas de segundo.|Mesura fins a centèsimes de segon.|It measures to hundredths of a second.'),
    M('¿En qué unidad se miden las fuerzas?|En quina unitat es mesuren les forces?|What unit is force measured in?', 'newtons (N)|newtons (N)|newtons (N)', ['litros|litres|litres', 'grados|graus|degrees'], 'En honor de Isaac Newton.|En honor d’Isaac Newton.|Named after Isaac Newton.'),
    M('En una bici, el plato grande y el piñón pequeño hacen que…|En una bici, el plat gran i el pinyó xicotet fan que…|On a bike, a big front cog and a small back cog make…', 'la rueda gire más deprisa|la roda gire més de pressa|the wheel turn faster', ['la bici se pare|la bici es pare|the bike stop', 'no cambie nada|no canvie res|no difference'], 'Una vuelta de pedal da varias vueltas de rueda.|Una volta de pedal fa diverses voltes de roda.|One turn of the pedals gives several wheel turns.'),
  ]),
  '6P-CM-6': lesson(['Para presentar un trabajo con diapositivas: poco texto, imágenes claras, letra grande y una idea por diapositiva. Cita siempre de dónde salen las imágenes y datos.|Per a presentar un treball amb diapositives: poc text, imatges clares, lletra gran i una idea per diapositiva. Cita sempre d’on ixen les imatges i dades.|To present work with slides: little text, clear images, large print and one idea per slide. Always say where images and data come from.', 'Un vídeo necesita un guion: qué se cuenta, en qué orden y con qué imágenes. Antes de publicar, pide permiso a quien aparezca.|Un vídeo necessita un guió: què es conta, en quin ordre i amb quines imatges. Abans de publicar, demana permís a qui aparega.|A video needs a script: what to say, in what order and with what images. Before posting, ask permission from anyone who appears.'],
    '¿Cómo debe ser una buena diapositiva?|Com ha de ser una bona diapositiva?|What makes a good slide?', ['El público escucha más que lee.|El públic escolta més que llig.|The audience listens more than it reads.', 'Una idea, pocas palabras y una imagen clara.|Una idea, poques paraules i una imatge clara.|One idea, few words and a clear image.'], [
    M('¿Qué es un error común en una presentación?|Quin és un error comú en una presentació?|What is a common mistake in a presentation?', 'leer párrafos enteros de la diapositiva|llegir paràgrafs sencers de la diapositiva|reading whole paragraphs off the slide', ['usar letra grande|usar lletra gran|using large print', 'poner imágenes claras|posar imatges clares|using clear images'], 'Mejor pocas palabras y explicarlas.|Millor poques paraules i explicar-les.|Better to use few words and explain them.'),
    M('Antes de grabar un vídeo, ¿qué conviene preparar?|Abans de gravar un vídeo, què convé preparar?|Before filming a video, what should you prepare?', 'un guion|un guió|a script', ['nada|res|nothing', 'solo la música|només la música|only the music'], 'Ordena lo que vas a contar.|Ordena el que contaràs.|It organises what you will say.'),
    TF('Para usar una foto de internet en un trabajo hay que indicar de dónde sale.|Per a usar una foto d’internet en un treball cal indicar d’on ix.|To use an internet photo in a project you must say where it comes from.', true, 'Respeta la autoría.|Respecta l’autoria.|It respects the creator.'),
    M('Antes de subir un vídeo en el que salen tus compañeros, ¿qué haces?|Abans de pujar un vídeo en què ixen els teus companys, què fas?|Before posting a video showing your classmates, what do you do?', 'pedirles permiso|demanar-los permís|ask their permission', ['subirlo sin decir nada|pujar-lo sense dir res|post it without saying anything', 'cambiarles la cara|canviar-los la cara|change their faces'], 'Su imagen es suya.|La seua imatge és seua.|Their image belongs to them.'),
    M('¿Qué tamaño de letra es mejor para una diapositiva?|Quina grandària de lletra és millor per a una diapositiva?|What font size is best for a slide?', 'grande, para leer desde lejos|gran, per a llegir de lluny|large, readable from a distance', ['muy pequeño|molt xicotet|very small', 'diferente en cada palabra|diferent en cada paraula|different for every word'], 'La clase debe poder leerla.|La classe ha de poder llegir-la.|The class must be able to read it.'),
    M('¿Qué herramienta sirve para hacer una presentación?|Quina eina servix per a fer una presentació?|Which tool is used to make a presentation?', 'un programa de diapositivas|un programa de diapositives|a slide program', ['una calculadora|una calculadora|a calculator', 'un termómetro|un termòmetre|a thermometer'], 'Ordena ideas e imágenes en pantallas.|Ordena idees i imatges en pantalles.|It arranges ideas and images on screens.'),
  ]),
  '6P-CM-7': lesson(['El ciberacoso es molestar, amenazar o humillar a alguien de forma repetida por internet o el móvil. Hace mucho daño.|El ciberassetjament és molestar, amenaçar o humiliar algú de manera repetida per internet o el mòbil. Fa molt de mal.|Cyberbullying is repeatedly bothering, threatening or humiliating someone online or by phone. It is very hurtful.', 'Si lo sufres o lo ves: no respondas, guarda pruebas (capturas), bloquea y cuéntaselo a un adulto de confianza. También hay que cuidar el tiempo de pantallas para evitar la adicción.|Si el patixes o el veus: no respongues, guarda proves (captures), bloqueja i conta-ho a un adult de confiança. També cal cuidar el temps de pantalles per a evitar l’addicció.|If it happens to you or you see it: do not reply, keep evidence (screenshots), block and tell a trusted adult. Also keep screen time in check to avoid addiction.'],
    'En el grupo de la clase se burlan cada día de un compañero. ¿Qué haces?|En el grup de la classe es burlen cada dia d’un company. Què fas?|In the class group chat, people mock a classmate every day. What do you do?', ['Es ciberacoso: no hay que reírse ni reenviar.|És ciberassetjament: no cal riure ni reenviar.|It is cyberbullying: do not laugh or forward it.', 'Guardo capturas, apoyo al compañero y aviso a un adulto.|Guarde captures, done suport al company i avise un adult.|I save screenshots, support the classmate and tell an adult.'], [
    M('¿Qué es el ciberacoso?|Què és el ciberassetjament?|What is cyberbullying?', 'molestar o humillar a alguien repetidamente por internet|molestar o humiliar algú repetidament per internet|repeatedly bothering or humiliating someone online', ['una broma sin importancia|una broma sense importància|a harmless joke', 'un videojuego|un videojoc|a video game'], 'Es repetido y hace daño.|És repetit i fa mal.|It is repeated and hurtful.'),
    M('Si te acosan por internet, ¿qué NO debes hacer?|Si t’assetgen per internet, què NO has de fer?|If you are bullied online, what should you NOT do?', 'contestar con insultos|contestar amb insults|reply with insults', ['guardar pruebas|guardar proves|keep evidence', 'contárselo a un adulto|contar-ho a un adult|tell an adult'], 'Responder suele empeorarlo.|Respondre sol empitjorar-ho.|Replying often makes it worse.'),
    TF('Reenviar un mensaje que humilla a alguien también es participar en el acoso.|Reenviar un missatge que humilia algú també és participar en l’assetjament.|Forwarding a humiliating message is also taking part in bullying.', true, 'Hace que más gente lo vea.|Fa que més gent el veja.|It spreads it to more people.'),
    M('¿Qué señal puede indicar uso excesivo de pantallas?|Quin senyal pot indicar ús excessiu de pantalles?|Which sign may show too much screen use?', 'enfadarse mucho cuando hay que dejarlas|enfadar-se molt quan cal deixar-les|getting very upset when you have to stop', ['leer un libro|llegir un llibre|reading a book', 'jugar en el parque|jugar en el parc|playing in the park'], 'Es mejor marcar horarios.|És millor marcar horaris.|It helps to set time limits.'),
    M('¿Para qué sirve guardar capturas de pantalla del acoso?|Per a què servix guardar captures de pantalla de l’assetjament?|Why save screenshots of bullying?', 'como pruebas para que los adultos actúen|com a proves perquè els adults actuen|as evidence so adults can act', ['para reírse después|per a riure’s després|to laugh at later', 'para enviarlas a todos|per a enviar-les a tots|to send to everyone'], 'Ayudan a demostrar lo ocurrido.|Ajuden a demostrar el que ha passat.|They prove what happened.'),
    M('¿Qué hábito ayuda al bienestar digital?|Quin hàbit ajuda al benestar digital?|Which habit supports digital wellbeing?', 'dejar el móvil fuera del dormitorio por la noche|deixar el mòbil fora del dormitori per la nit|leaving the phone outside the bedroom at night', ['mirar el móvil cada minuto|mirar el mòbil cada minut|checking the phone every minute', 'dormir con la tableta encendida|dormir amb la tauleta encesa|sleeping with the tablet on'], 'El descanso es importante.|El descans és important.|Rest matters.'),
  ]),
  '6P-CM-8': lesson(['La huella digital es el rastro que dejamos en internet: fotos, comentarios, búsquedas, «me gusta». Es difícil de borrar y otras personas pueden verla en el futuro.|La petjada digital és el rastre que deixem a internet: fotos, comentaris, cerques, «m’agrada». És difícil d’esborrar i altres persones poden veure-la en el futur.|Your digital footprint is the trail you leave online: photos, comments, searches, likes. It is hard to delete and others may see it in the future.', 'La propiedad intelectual protege a quien crea textos, imágenes, música o vídeos. Usa contenido con licencia libre o cita siempre a su autor.|La propietat intel·lectual protegix qui crea textos, imatges, música o vídeos. Usa contingut amb llicència lliure o cita sempre el seu autor.|Intellectual property protects people who create texts, images, music or videos. Use openly licensed content or always credit the creator.'],
    'Vas a subir una foto graciosa de un amigo. ¿Qué piensas antes?|Pujaràs una foto graciosa d’un amic. Què penses abans?|You are about to post a funny photo of a friend. What should you think first?', ['Quedará en su huella digital.|Quedarà en la seua petjada digital.|It will stay in his digital footprint.', '¿Le gustaría que se viera dentro de unos años? Le pido permiso.|Li agradaria que es veiera d’ací a uns anys? Li demane permís.|Would he want people to see it years from now? I ask him first.'], [
    M('¿Qué forma parte de tu huella digital?|Què forma part de la teua petjada digital?|What is part of your digital footprint?', 'los comentarios que publicas|els comentaris que publiques|comments you post', ['lo que sueñas|el que somies|your dreams', 'lo que comes en casa sin contarlo|el que menges a casa sense contar-ho|what you eat at home without sharing it'], 'Todo lo que dejas en internet.|Tot el que deixes a internet.|Everything you leave online.'),
    TF('Lo que se publica en internet se puede borrar siempre del todo.|El que es publica a internet es pot esborrar sempre del tot.|Anything posted online can always be completely deleted.', false, 'Alguien puede haberlo copiado o guardado.|Algú pot haver-ho copiat o guardat.|Someone may have copied or saved it.'),
    M('¿Qué significa una licencia Creative Commons?|Què significa una llicència Creative Commons?|What does a Creative Commons licence mean?', 'que el autor permite usar su obra con ciertas condiciones|que l’autor permet usar la seua obra amb certes condicions|the creator lets you use the work under certain conditions', ['que se puede vender sin permiso|que es pot vendre sense permís|you can sell it without permission', 'que no tiene autor|que no té autor|it has no creator'], 'Suele pedir que cites al autor.|Sol demanar que cites l’autor.|It usually asks you to credit the creator.'),
    M('Para tu trabajo usas una canción de otra persona. ¿Qué haces?|Per al teu treball uses una cançó d’una altra persona. Què fas?|You use someone else’s song in your project. What do you do?', 'Indico el autor y compruebo que se puede usar|Indique l’autor i comprove que es pot usar|Credit the artist and check it can be used', ['Digo que es mía|Dic que és meua|Say it is mine', 'No digo nada|No dic res|Say nothing'], 'Respeta la propiedad intelectual.|Respecta la propietat intel·lectual.|Respect intellectual property.'),
    M('¿Qué dato NO conviene publicar en una red social?|Quina dada NO convé publicar en una xarxa social?|Which detail should you NOT post on social media?', 'la dirección de tu casa|l’adreça de casa|your home address', ['tu dibujo favorito|el teu dibuix preferit|your favourite drawing', 'tu libro preferido|el teu llibre preferit|your favourite book'], 'Es un dato personal sensible.|És una dada personal sensible.|It is sensitive personal information.'),
    M('Copiar un trabajo de internet y presentarlo como propio se llama…|Copiar un treball d’internet i presentar-lo com a propi es diu…|Copying work from the internet and presenting it as your own is…', 'plagio|plagi|plagiarism', ['investigación|investigació|research', 'resumen|resum|a summary'], 'No es honesto.|No és honest.|It is dishonest.'),
  ]),
  '6P-CM-9': lesson(['Para estudiar algo con datos: formula una pregunta, recoge datos (encuesta, medidas), organízalos en una tabla y represéntalos en un gráfico adecuado.|Per a estudiar una cosa amb dades: formula una pregunta, recull dades (enquesta, mesures), organitza-les en una taula i representa-les en un gràfic adequat.|To study something with data: ask a question, collect data (survey, measurements), organise it in a table and show it in a suitable graph.', 'Gráfico de barras para comparar categorías; de líneas para ver cambios en el tiempo; de sectores para ver partes de un total.|Gràfic de barres per a comparar categories; de línies per a veure canvis en el temps; de sectors per a veure parts d’un total.|Bar charts to compare categories; line graphs for change over time; pie charts for parts of a whole.'],
    'Quieres mostrar cómo cambia la temperatura durante una semana. ¿Qué gráfico usas?|Vols mostrar com canvia la temperatura durant una setmana. Quin gràfic uses?|You want to show how temperature changes over a week. Which graph do you use?', ['Es un cambio a lo largo del tiempo.|És un canvi al llarg del temps.|It is a change over time.', 'Un gráfico de líneas.|Un gràfic de línies.|A line graph.'], [
    M('Para comparar los deportes favoritos de la clase, ¿qué gráfico es mejor?|Per a comparar els esports preferits de la classe, quin gràfic és millor?|To compare the class’s favourite sports, which graph is best?', 'de barras|de barres|a bar chart', ['de líneas|de línies|a line graph', 'ninguno|cap|none'], 'Compara categorías.|Compara categories.|It compares categories.'),
    M('Para mostrar qué parte del día dedicas a cada actividad, ¿qué gráfico usas?|Per a mostrar quina part del dia dediques a cada activitat, quin gràfic uses?|To show what part of your day goes on each activity, which graph do you use?', 'de sectores|de sectors|a pie chart', ['de líneas|de línies|a line graph', 'de dispersión|de dispersió|a scatter graph'], 'Partes de un total.|Parts d’un total.|Parts of a whole.'),
    M('¿Qué haces primero en un estudio con datos?|Què fas primer en un estudi amb dades?|What comes first in a data study?', 'formular una pregunta|formular una pregunta|asking a question', ['hacer el gráfico|fer el gràfic|drawing the graph', 'escribir la conclusión|escriure la conclusió|writing the conclusion'], 'Sin pregunta no sabes qué datos buscar.|Sense pregunta no saps quines dades buscar.|Without a question you do not know what data to look for.'),
    TF('Una hoja de cálculo ayuda a ordenar datos y hacer gráficos.|Un full de càlcul ajuda a ordenar dades i fer gràfics.|A spreadsheet helps organise data and make graphs.', true, 'Calcula y dibuja automáticamente.|Calcula i dibuixa automàticament.|It calculates and draws automatically.'),
    Nq('En una encuesta, 6 eligen fútbol, 4 baloncesto y 10 natación. ¿Cuántas personas respondieron?|En una enquesta, 6 trien futbol, 4 bàsquet i 10 natació. Quantes persones van respondre?|In a survey, 6 chose football, 4 basketball and 10 swimming. How many people answered?', 20, [10, 16, 14], 'Suma todas las respuestas.|Suma totes les respostes.|Add all the answers.'),
    M('¿Qué debe tener siempre un gráfico?|Què ha de tindre sempre un gràfic?|What should every graph have?', 'título y ejes con nombre|títol i eixos amb nom|a title and labelled axes', ['muchos colores|molts colors|lots of colours', 'ningún texto|cap text|no text'], 'Así se entiende qué muestra.|Així s’entén què mostra.|So people understand it.'),
  ]),
  '6P-CM-10': lesson(['Los ordenadores trabajan con lógica de sí o no (verdadero o falso, 1 o 0). Con «Y» las dos condiciones deben cumplirse; con «O», basta una; «NO» cambia el valor.|Els ordinadors treballen amb lògica de sí o no (vertader o fals, 1 o 0). Amb «I» les dues condicions s’han de complir; amb «O», n’hi ha prou amb una; «NO» canvia el valor.|Computers work with yes/no logic (true or false, 1 or 0). With AND both conditions must be true; with OR one is enough; NOT flips the value.', 'Buscar patrones (lo que se repite) ayuda a resolver problemas más rápido.|Buscar patrons (el que es repetix) ajuda a resoldre problemes més ràpid.|Looking for patterns (what repeats) helps solve problems faster.'],
    'Sales al patio si «no llueve Y has acabado la tarea». Hoy no llueve, pero no has acabado. ¿Sales?|Ixes al pati si «no plou I has acabat la tasca». Hui no plou, però no has acabat. Ixes?|You can go outside if "it is not raining AND you have finished your work". It is not raining but you have not finished. Do you go out?', ['Con «Y» deben cumplirse las dos.|Amb «I» s’han de complir les dues.|With AND both must be true.', 'Una es falsa: no sales.|Una és falsa: no ixes.|One is false: you do not go out.'], [
    M('«Ganas un premio si sacas un 6 O un 1». Sacas un 1. ¿Ganas?|«Guanyes un premi si traus un 6 O un 1». Traus un 1. Guanyes?|"You win if you roll a 6 OR a 1". You roll a 1. Do you win?', 'Sí|Sí|Yes', ['No|No|No'], 'Con «O» basta una condición.|Amb «O» n’hi ha prou amb una condició.|With OR one condition is enough.'),
    M('«Entras si tienes entrada Y más de 10 años». Tienes 12 años pero no entrada. ¿Entras?|«Entres si tens entrada I més de 10 anys». Tens 12 anys però no entrada. Entres?|"You get in if you have a ticket AND are over 10". You are 12 but have no ticket. Do you get in?', 'No|No|No', ['Sí|Sí|Yes'], 'Con «Y» se necesitan las dos.|Amb «I» calen les dues.|With AND you need both.'),
    M('Si algo es verdadero, ¿qué es «NO verdadero»?|Si una cosa és vertadera, què és «NO vertader»?|If something is true, what is "NOT true"?', 'falso|fals|false', ['verdadero|vertader|true'], 'NO invierte el valor.|NO inverteix el valor.|NOT flips the value.'),
    M('¿Qué número sigue el patrón 1, 0, 1, 0, 1, …?|Quin nombre seguix el patró 1, 0, 1, 0, 1, …?|What comes next in the pattern 1, 0, 1, 0, 1, …?', '0|0|0', ['1|1|1', '2|2|2'], 'Se alternan 1 y 0.|S’alternen 1 i 0.|1 and 0 alternate.'),
    TF('Los ordenadores representan la información con ceros y unos.|Els ordinadors representen la informació amb zeros i uns.|Computers represent information with zeros and ones.', true, 'Es el sistema binario.|És el sistema binari.|That is the binary system.'),
    M('Una lámpara se enciende si «es de noche O pulsas el botón». Es de día y pulsas el botón. ¿Se enciende?|Una làmpada s’encén si «és de nit O prems el botó». És de dia i prems el botó. S’encén?|A lamp turns on if "it is night OR you press the button". It is daytime and you press the button. Does it turn on?', 'Sí|Sí|Yes', ['No|No|No'], 'Basta con una de las dos.|N’hi ha prou amb una de les dues.|One of them is enough.'),
  ]),
  '6P-CM-11': lesson(['Los sensores detectan cosas del entorno (luz, temperatura, distancia, movimiento) y los actuadores responden (motores que giran, luces que se encienden, zumbadores que suenan). Una placa controladora decide qué hacer según el programa.|Els sensors detecten coses de l’entorn (llum, temperatura, distància, moviment) i els actuadors responen (motors que giren, llums que s’encenen, brunzidors que sonen). Una placa controladora decidix què fer segons el programa.|Sensors detect things around them (light, temperature, distance, movement) and actuators respond (motors that turn, lights that switch on, buzzers that sound). A controller board decides what to do based on the program.', 'Así funcionan las puertas automáticas, las farolas que se encienden solas o los robots aspiradores.|Així funcionen les portes automàtiques, els fanals que s’encenen sols o els robots aspiradors.|That is how automatic doors, self-lighting streetlamps and robot vacuums work.'],
    'Una farola se enciende sola cuando oscurece. ¿Qué sensor usa?|Un fanal s’encén sol quan es fa fosc. Quin sensor usa?|A streetlamp switches on by itself at dusk. Which sensor does it use?', ['Detecta la cantidad de luz.|Detecta la quantitat de llum.|It detects the amount of light.', 'Un sensor de luz.|Un sensor de llum.|A light sensor.'], [
    M('Un robot aspirador no choca con la pared. ¿Qué sensor usa?|Un robot aspirador no xoca amb la paret. Quin sensor usa?|A robot vacuum does not hit walls. Which sensor does it use?', 'de distancia|de distància|a distance sensor', ['de temperatura|de temperatura|a temperature sensor', 'de humedad|d’humitat|a humidity sensor'], 'Mide lo cerca que está de un obstáculo.|Mesura com d’a prop està d’un obstacle.|It measures how close an obstacle is.'),
    M('¿Qué es un actuador?|Què és un actuador?|What is an actuator?', 'un elemento que actúa, como un motor o una luz|un element que actua, com un motor o una llum|a part that acts, like a motor or light', ['un sensor|un sensor|a sensor', 'un cable|un cable|a cable'], 'Hace algo en el entorno.|Fa alguna cosa en l’entorn.|It does something to the surroundings.'),
    M('¿Qué decide lo que hace un robot según lo que detectan los sensores?|Què decidix el que fa un robot segons el que detecten els sensors?|What decides what a robot does based on its sensors?', 'la placa controladora con su programa|la placa controladora amb el seu programa|the controller board running its program', ['la pila|la pila|the battery', 'la carcasa|la carcassa|the case'], 'Es el «cerebro» del robot.|És el «cervell» del robot.|It is the robot’s "brain".'),
    TF('Una puerta automática usa un sensor de movimiento.|Una porta automàtica usa un sensor de moviment.|An automatic door uses a motion sensor.', true, 'Detecta que alguien se acerca.|Detecta que algú s’acosta.|It detects someone approaching.'),
    M('En un invernadero automático, si la temperatura sube mucho, ¿qué podría hacer el programa?|En un hivernacle automàtic, si la temperatura puja molt, què podria fer el programa?|In an automatic greenhouse, if it gets very hot, what might the program do?', 'encender un ventilador|encendre un ventilador|switch on a fan', ['apagar las luces de la calle|apagar els llums del carrer|switch off the streetlights', 'nada nunca|res mai|never do anything'], 'Sensor de temperatura → actuador ventilador.|Sensor de temperatura → actuador ventilador.|Temperature sensor → fan actuator.'),
    M('¿Qué es la realidad aumentada?|Què és la realitat augmentada?|What is augmented reality?', 'añadir imágenes digitales a lo que ves con la cámara|afegir imatges digitals al que veus amb la càmera|adding digital images to what you see through a camera', ['un juego de mesa|un joc de taula|a board game', 'una pila más grande|una pila més gran|a bigger battery'], 'Mezcla lo real con lo digital.|Mescla el real amb el digital.|It mixes real and digital.'),
  ]),
  '6P-CM-12': lesson(['En el mundo hay zonas climáticas: cálida (cerca del ecuador), templadas y frías (cerca de los polos). España tiene sobre todo clima mediterráneo y continental, y atlántico en el norte.|En el món hi ha zones climàtiques: càlida (prop de l’equador), temperades i fredes (prop dels pols). Espanya té sobretot clima mediterrani i continental, i atlàntic al nord.|The world has climate zones: hot (near the equator), temperate and cold (near the poles). Spain has mainly Mediterranean and continental climates, with an Atlantic climate in the north.', 'Frente al cambio climático: reducir emisiones (energía limpia, transporte público), adaptarse (ahorrar agua, más zonas verdes) y proteger los bosques.|Davant del canvi climàtic: reduir emissions (energia neta, transport públic), adaptar-se (estalviar aigua, més zones verdes) i protegir els boscos.|Against climate change: cut emissions (clean energy, public transport), adapt (save water, more green spaces) and protect forests.'],
    '¿Qué clima tiene la costa valenciana?|Quin clima té la costa valenciana?|What climate does the Valencian coast have?', ['Veranos calurosos y secos, inviernos suaves.|Estius calorosos i secs, hiverns suaus.|Hot dry summers and mild winters.', 'Mediterráneo.|Mediterrani.|Mediterranean.'], [
    M('¿Dónde está la zona cálida de la Tierra?|On està la zona càlida de la Terra?|Where is the Earth’s hot zone?', 'cerca del ecuador|prop de l’equador|near the equator', ['en los polos|als pols|at the poles', 'solo en Europa|només a Europa|only in Europe'], 'Los rayos del sol llegan más directos.|Els raigs del sol arriben més directes.|The sun’s rays arrive more directly.'),
    M('El clima con lluvias frecuentes y temperaturas suaves del norte de España es…|El clima amb pluges freqüents i temperatures suaus del nord d’Espanya és…|The rainy, mild climate of northern Spain is…', 'atlántico (oceánico)|atlàntic (oceànic)|Atlantic (oceanic)', ['desértico|desèrtic|desert', 'polar|polar|polar'], 'Le llega humedad del océano.|Li arriba humitat de l’oceà.|Moisture comes from the ocean.'),
    M('¿Qué acción reduce las emisiones?|Quina acció reduïx les emissions?|Which action cuts emissions?', 'usar el transporte público|usar el transport públic|using public transport', ['dejar el coche en marcha parado|deixar el cotxe en marxa parat|leaving the car idling', 'quemar rastrojos|cremar rostolls|burning stubble'], 'Menos coches, menos gases.|Menys cotxes, menys gasos.|Fewer cars, fewer gases.'),
    TF('Plantar árboles ayuda a frenar el cambio climático.|Plantar arbres ajuda a frenar el canvi climàtic.|Planting trees helps slow climate change.', true, 'Absorben dióxido de carbono.|Absorbixen diòxid de carboni.|They absorb carbon dioxide.'),
    M('El clima continental del interior de España tiene…|El clima continental de l’interior d’Espanya té…|The continental climate of inland Spain has…', 'inviernos fríos y veranos calurosos|hiverns freds i estius calorosos|cold winters and hot summers', ['temperaturas iguales todo el año|temperatures iguals tot l’any|the same temperature all year', 'lluvia todos los días|pluja tots els dies|rain every day'], 'Lejos del mar, los contrastes son mayores.|Lluny de la mar, els contrastos són majors.|Far from the sea, the contrasts are bigger.'),
    M('Adaptarse al cambio climático incluye…|Adaptar-se al canvi climàtic inclou…|Adapting to climate change includes…', 'crear más zonas verdes y ahorrar agua|crear més zones verdes i estalviar aigua|more green spaces and saving water', ['gastar más agua|gastar més aigua|using more water', 'asfaltar los parques|asfaltar els parcs|tarmacking parks'], 'Prepararse para más calor y sequías.|Preparar-se per a més calor i sequeres.|Preparing for more heat and drought.'),
  ]),
  '6P-CM-13': lesson(['Europa tiene grandes llanuras (como la gran llanura europea), cordilleras (Alpes, Pirineos, Cárpatos, Urales) y penínsulas (Ibérica, Itálica, Escandinava, Balcánica). Sus ríos más largos son el Volga y el Danubio.|Europa té grans planes (com la gran plana europea), serralades (Alps, Pirineus, Carpats, Urals) i penínsules (Ibèrica, Itàlica, Escandinava, Balcànica). Els seus rius més llargs són el Volga i el Danubi.|Europe has great plains (such as the Great European Plain), mountain ranges (Alps, Pyrenees, Carpathians, Urals) and peninsulas (Iberian, Italian, Scandinavian, Balkan). Its longest rivers are the Volga and the Danube.', 'Los paisajes agrarios (campos, huertas) y turísticos (costas, estaciones de esquí) son paisajes humanizados.|Els paisatges agraris (camps, hortes) i turístics (costes, estacions d’esquí) són paisatges humanitzats.|Farming landscapes (fields, market gardens) and tourist landscapes (coasts, ski resorts) are human-made landscapes.'],
    '¿Qué cordillera separa España de Francia?|Quina serralada separa Espanya de França?|Which mountain range separates Spain from France?', ['Está al norte de la península.|Està al nord de la península.|It is in the north of the peninsula.', 'Los Pirineos.|Els Pirineus.|The Pyrenees.'], [
    M('¿Cuál es la cordillera más alta de Europa occidental?|Quina és la serralada més alta d’Europa occidental?|Which is the highest range in western Europe?', 'los Alpes|els Alps|the Alps', ['los Pirineos|els Pirineus|the Pyrenees', 'los Urales|els Urals|the Urals'], 'Allí está el Mont Blanc.|Allí hi ha el Mont Blanc.|Mont Blanc is there.'),
    M('¿En qué península está España?|En quina península està Espanya?|Which peninsula is Spain on?', 'Ibérica|Ibèrica|Iberian', ['Itálica|Itàlica|Italian', 'Escandinava|Escandinava|Scandinavian'], 'La comparte con Portugal.|La compartix amb Portugal.|It shares it with Portugal.'),
    M('¿Qué río europeo es el más largo?|Quin riu europeu és el més llarg?|Which is Europe’s longest river?', 'el Volga|el Volga|the Volga', ['el Ebro|l’Ebre|the Ebro', 'el Turia|el Túria|the Turia'], 'Está en Rusia.|Està a Rússia.|It is in Russia.'),
    TF('Una estación de esquí es un paisaje humanizado.|Una estació d’esquí és un paisatge humanitzat.|A ski resort is a human-made landscape.', true, 'Tiene pistas, remontes y edificios.|Té pistes, remuntadors i edificis.|It has runs, lifts and buildings.'),
    M('La huerta valenciana es un ejemplo de paisaje…|L’horta valenciana és un exemple de paisatge…|The Valencian huerta is an example of a… landscape', 'agrario|agrari|farming', ['natural sin cambios|natural sense canvis|untouched natural', 'industrial|industrial|industrial'], 'Hay cultivos y acequias.|Hi ha cultius i séquies.|There are crops and irrigation channels.'),
    M('¿Qué montañas marcan el límite entre Europa y Asia?|Quines muntanyes marquen el límit entre Europa i Àsia?|Which mountains mark the border between Europe and Asia?', 'los Urales|els Urals|the Urals', ['los Alpes|els Alps|the Alps', 'los Apeninos|els Apenins|the Apennines'], 'Están en Rusia.|Estan a Rússia.|They are in Russia.'),
  ]),
  '6P-CM-14': lesson(['El agua dulce disponible es escasa y está repartida de forma desigual. En la Comunitat Valenciana hay épocas de sequía, por eso es clave usarla bien.|L’aigua dolça disponible és escassa i està repartida de manera desigual. A la Comunitat Valenciana hi ha èpoques de sequera, per això és clau usar-la bé.|Available fresh water is scarce and unevenly shared. The Valencian Community has periods of drought, so using water well is vital.', 'La agricultura usa la mayor parte del agua: el riego por goteo ahorra mucha. En casa, cada gesto cuenta.|L’agricultura usa la major part de l’aigua: el reg per degoteig n’estalvia molta. A casa, cada gest compta.|Farming uses most of the water: drip irrigation saves a lot. At home, every action counts.'],
    '¿Qué sistema de riego ahorra más agua?|Quin sistema de reg estalvia més aigua?|Which irrigation system saves most water?', ['Lleva el agua justo a la raíz, gota a gota.|Porta l’aigua just a l’arrel, gota a gota.|It delivers water drop by drop right to the roots.', 'El riego por goteo.|El reg per degoteig.|Drip irrigation.'], [
    M('¿Qué actividad usa más agua dulce en el mundo?|Quina activitat usa més aigua dolça en el món?|Which activity uses the most fresh water worldwide?', 'la agricultura|l’agricultura|farming', ['beber|beure|drinking', 'lavarse los dientes|rentar-se les dents|brushing teeth'], 'Regar cultivos necesita mucha agua.|Regar cultius necessita molta aigua.|Watering crops takes a lot.'),
    M('¿Qué es una sequía?|Què és una sequera?|What is a drought?', 'un periodo largo con muy poca lluvia|un període llarg amb molt poca pluja|a long period with very little rain', ['una inundación|una inundació|a flood', 'un día de viento|un dia de vent|a windy day'], 'Bajan los embalses y los ríos.|Baixen els embassaments i els rius.|Reservoirs and rivers fall.'),
    TF('La mayor parte del agua de la Tierra es salada.|La major part de l’aigua de la Terra és salada.|Most of the Earth’s water is salt water.', true, 'Mares y océanos.|Mars i oceans.|Seas and oceans.'),
    M('¿Qué instalación convierte agua de mar en agua dulce?|Quina instal·lació convertix aigua de mar en aigua dolça?|Which facility turns seawater into fresh water?', 'la desaladora|la dessalinitzadora|a desalination plant', ['la depuradora|la depuradora|a sewage works', 'la presa|la presa|a dam'], 'Quita la sal del agua.|Lleva la sal de l’aigua.|It removes salt from water.'),
    M('¿Qué gesto doméstico ahorra agua?|Quin gest domèstic estalvia aigua?|Which household habit saves water?', 'poner la lavadora llena|posar la rentadora plena|running the washing machine full', ['ducharse 20 minutos|dutxar-se 20 minuts|20-minute showers', 'regar a mediodía en verano|regar a migdia a l’estiu|watering at midday in summer'], 'Aprovechas cada lavado.|Aprofites cada rentada.|Each wash is used fully.'),
    M('Las acequias de la huerta sirven para…|Les séquies de l’horta servixen per a…|Irrigation channels in the huerta are for…', 'repartir el agua de riego|repartir l’aigua de reg|sharing out irrigation water', ['bañarse|banyar-se|swimming', 'pescar|pescar|fishing'], 'El Tribunal de las Aguas las regula desde hace siglos.|El Tribunal de les Aigües les regula des de fa segles.|The Water Tribunal has governed them for centuries.'),
  ]),
  '6P-CM-15': lesson(['Como consumidores tenemos derechos: información clara, productos seguros, poder reclamar y que nos devuelvan el dinero si algo está defectuoso.|Com a consumidors tenim drets: informació clara, productes segurs, poder reclamar i que ens tornen els diners si una cosa és defectuosa.|As consumers we have rights: clear information, safe products, the right to complain and a refund for faulty goods.', 'También deberes ecológicos: elegir productos sostenibles, reparar, reutilizar y separar residuos.|També deures ecològics: triar productes sostenibles, reparar, reutilitzar i separar residus.|And green duties: choosing sustainable products, repairing, reusing and sorting waste.'],
    'Compras un juguete y se rompe al primer uso. ¿Qué derecho tienes?|Compres un joguet i es trenca al primer ús. Quin dret tens?|You buy a toy and it breaks the first time you use it. What right do you have?', ['Es un producto defectuoso.|És un producte defectuós.|It is a faulty product.', 'Reclamar con el tique: que lo cambien o te devuelvan el dinero.|Reclamar amb el tiquet: que el canvien o et tornen els diners.|Complain with the receipt: get a replacement or a refund.'], [
    M('¿Qué documento debes guardar para poder reclamar?|Quin document has de guardar per a poder reclamar?|What document should you keep so you can complain?', 'el tique de compra|el tiquet de compra|the receipt', ['la bolsa|la bossa|the bag', 'la publicidad|la publicitat|the advert'], 'Demuestra dónde y cuándo compraste.|Demostra on i quan vas comprar.|It proves where and when you bought it.'),
    TF('Los consumidores tienen derecho a recibir información clara sobre los productos.|Els consumidors tenen dret a rebre informació clara sobre els productes.|Consumers have the right to clear information about products.', true, 'Por eso existen las etiquetas.|Per això existixen les etiquetes.|That is why labels exist.'),
    M('¿Qué es un deber del consumidor ecológico?|Què és un deure del consumidor ecològic?|Which is a duty of a green consumer?', 'separar los residuos|separar els residus|sorting waste', ['comprar siempre lo más nuevo|comprar sempre el més nou|always buying the newest thing', 'tirar lo que se puede reparar|tirar el que es pot reparar|throwing away what can be repaired'], 'Ayuda a reciclar.|Ajuda a reciclar.|It helps recycling.'),
    M('¿Qué sello indica un producto más respetuoso con el medio ambiente?|Quin segell indica un producte més respectuós amb el medi ambient?|Which label shows a more eco-friendly product?', 'la etiqueta ecológica|l’etiqueta ecològica|the eco-label', ['un dibujo bonito|un dibuix bonic|a pretty picture', 'el precio alto|el preu alt|a high price'], 'Lo certifica una entidad oficial.|Ho certifica una entitat oficial.|An official body certifies it.'),
    M('Antes de cambiar el móvil, ¿qué es más sostenible?|Abans de canviar el mòbil, què és més sostenible?|Before replacing your phone, what is more sustainable?', 'repararlo si se puede|reparar-lo si es pot|repairing it if possible', ['comprar uno nuevo cada año|comprar-ne un de nou cada any|buying a new one every year', 'tirarlo a la basura|tirar-lo al fem|binning it'], 'Alarga su vida útil.|Allarga la seua vida útil.|It extends its life.'),
    M('¿Dónde se puede reclamar si una tienda no atiende tu queja?|On es pot reclamar si una botiga no atén la teua queixa?|Where can you complain if a shop ignores you?', 'en la Oficina de Consumo|en l’Oficina de Consum|the consumer office', ['en la biblioteca|en la biblioteca|the library', 'en el cine|en el cine|the cinema'], 'Defiende a los consumidores.|Defén els consumidors.|It protects consumers.'),
  ]),
  '6P-CM-16': lesson(['La publicidad quiere que compremos. Usa trucos: famosos, música pegadiza, «¡últimas unidades!», imágenes retocadas. Pensar con calma antes de comprar es consumir con criterio.|La publicitat vol que comprem. Usa trucs: famosos, música enganxosa, «últimes unitats!», imatges retocades. Pensar amb calma abans de comprar és consumir amb criteri.|Advertising wants us to buy. It uses tricks: celebrities, catchy music, "last few left!", retouched images. Thinking calmly before buying is consuming wisely.', 'La etiqueta dice qué es de verdad el producto: ingredientes, fecha de caducidad, origen, precio por kilo y cómo reciclar el envase.|L’etiqueta diu què és de veritat el producte: ingredients, data de caducitat, origen, preu per quilo i com reciclar l’envàs.|The label tells you what the product really is: ingredients, use-by date, origin, price per kilo and how to recycle the packaging.'],
    'Un anuncio dice: «¡Solo hoy! ¡Compra ya!». ¿Qué truco usa?|Un anunci diu: «Només hui! Compra ja!». Quin truc usa?|An advert says: "Today only! Buy now!". What trick is it using?', ['Te mete prisa para que no pienses.|Et posa pressa perquè no penses.|It rushes you so you do not think.', 'La urgencia. Mejor pensarlo con calma.|La urgència. Millor pensar-ho amb calma.|Urgency. Better to think it over.'], [
    M('¿Dónde miras cuándo caduca un yogur?|On mires quan caduca un iogurt?|Where do you check when a yoghurt expires?', 'en la etiqueta|en l’etiqueta|on the label', ['en el anuncio de la tele|en l’anunci de la tele|in the TV advert', 'en el color|en el color|in its colour'], 'Pone «consumir preferentemente antes de» o «fecha de caducidad».|Posa «consumir preferentment abans de» o «data de caducitat».|It says "best before" or "use by".'),
    M('¿Para qué sirve el precio por kilo de la etiqueta?|Per a què servix el preu per quilo de l’etiqueta?|What is the price per kilo on the label for?', 'para comparar qué es más barato de verdad|per a comparar què és més barat de veritat|to compare which is really cheaper', ['para saber el peso del cliente|per a saber el pes del client|to know the shopper’s weight', 'para nada|per a res|nothing'], 'Paquetes de distinto tamaño se comparan así.|Paquets de diferent grandària es comparen així.|It lets you compare different-sized packs.'),
    TF('Las fotos de los anuncios siempre muestran el producto tal como es.|Les fotos dels anuncis sempre mostren el producte tal com és.|Advert photos always show the product exactly as it is.', false, 'A menudo están retocadas.|Sovint estan retocades.|They are often retouched.'),
    M('Un famoso anuncia unas zapatillas. ¿Qué quiere conseguir?|Un famós anuncia unes sabatilles. Què vol aconseguir?|A celebrity advertises trainers. What is the aim?', 'que las asocies a éxito y quieras comprarlas|que les associes a l’èxit i vulgues comprar-les|for you to link them with success and want them', ['que sean mejores|que siguen millors|to make them better', 'que bajen de precio|que baixen de preu|to make them cheaper'], 'Es un truco publicitario.|És un truc publicitari.|It is an advertising trick.'),
    M('¿Qué información de la etiqueta ayuda a reciclar?|Quina informació de l’etiqueta ajuda a reciclar?|Which label information helps with recycling?', 'el símbolo del contenedor|el símbol del contenidor|the bin symbol', ['el nombre de la marca|el nom de la marca|the brand name', 'el eslogan|l’eslògan|the slogan'], 'Indica dónde tirar el envase.|Indica on tirar l’envàs.|It shows where the packaging goes.'),
    M('Antes de comprar algo que has visto en un anuncio, ¿qué te preguntas?|Abans de comprar una cosa que has vist en un anunci, què et preguntes?|Before buying something you saw advertised, what do you ask yourself?', '¿Lo necesito de verdad?|De veritat ho necessite?|Do I really need it?', ['¿Sale en la tele?|Ix en la tele?|Is it on TV?', '¿Lo tiene un famoso?|El té un famós?|Does a celebrity have it?'], 'Consumir con criterio.|Consumir amb criteri.|Consume wisely.'),
  ]),
};
export default P;
